WITH customer_summary AS (SELECT customer_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(channel))) AS channel_values, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values FROM orders WHERE status IN ('SHIPPED', 'COMPLETED') GROUP BY customer_id) SELECT c.id, c.country, c.credit_limit, cs.channel_values, cs.status_values FROM customers c INNER JOIN customer_summary cs ON c.id = cs.customer_id ORDER BY credit_limit, 5;
